from __future__ import annotations

import pytest


class BoundedQueue:
    """Fixed-capacity FIFO queue of integers with non-blocking puts."""

    def __init__(self, capacity: int) -> None:
        """Create an empty queue that holds at most `capacity` items."""
        self._capacity: int = capacity
        self._items: list[int] = []

    def put_nowait(self, item: int) -> bool:
        """Append `item` if there is room.

        Returns True when the item was accepted, False when the queue is full.
        Never blocks.
        """
        if len(self._items) >= self._capacity:
            return False
        self._items.append(item)
        return True

    def __len__(self) -> int:
        """Number of items currently stored."""
        return len(self._items)


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many leading elements of `xs` are accepted by a queue of capacity `cap`.

    Put each element of `xs` into a BoundedQueue(cap) with put_nowait, in order.
    Stop at the first rejected put and return the number of accepted puts so far.
    A non-positive capacity accepts nothing.
    """
    q = BoundedQueue(cap)
    count = 0
    for x in xs:
        if not q.put_nowait(x):
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_empty_input() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2]) == 0


def test_bounded_queue_put_nowait_reports_full() -> None:
    q = BoundedQueue(1)
    assert q.put_nowait(7) is True
    assert q.put_nowait(8) is False
    assert len(q) == 1
